code='''from collections import deque
def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); out=[r[:] for r in grid]
    for i in range(h):
      for j in range(w):
        if grid[i][j]==0 or (i,j) in seen: continue
        q=deque([(i,j)]); seen.add((i,j)); cells=[]
        while q:
          r,c=q.popleft(); cells.append((r,c))
          for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=r+dr,c+dc
            if 0<=a<h and 0<=b<w and grid[a][b]!=0 and (a,b) not in seen:
              seen.add((a,b)); q.append((a,b))
        colors=set(grid[r][c] for r,c in cells)
        boxes={}
        for col in colors:
          pts=[(r,c) for r,c in cells if grid[r][c]==col]
          boxes[col]=(max(r for r,c in pts)-min(r for r,c in pts)+1)*(max(c for r,c in pts)-min(c for r,c in pts)+1)
        order=sorted(colors,key=lambda x:boxes[x], reverse=True)
        mp={a:b for a,b in zip(order,reversed(order))}
        for r,c in cells: out[r][c]=mp[grid[r][c]]
    return out
